<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/functions.php';$uid=usuarioLogado();$inicio=$_GET['inicio']??date('Y-m-01');$fim=$_GET['fim']??date('Y-m-t');
$stmt=db()->prepare('SELECT COALESCE(t.nome,\'Sem tipo\') tipo,SUM(r.valor) total,COUNT(*) quantidade FROM RECEBIMENTO r LEFT JOIN TIPO_RECEBIMENTO t ON t.id_tipo_recebimento=r.id_tipo_recebimento WHERE r.id_usuario=:u AND r.data_recebimento BETWEEN :i AND :f GROUP BY t.id_tipo_recebimento,t.nome ORDER BY total DESC');$stmt->execute(['u'=>$uid,'i'=>$inicio,'f'=>$fim]);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
$stmt=db()->prepare('SELECT COALESCE(SUM(valor),0) FROM RECEBIMENTO WHERE id_usuario=:u AND data_recebimento BETWEEN :i AND :f');$stmt->execute(['u'=>$uid,'i'=>$inicio,'f'=>$fim]);$total=(float)$stmt->fetchColumn();
$pageTitle='Relatório de receitas';$basePath='../';require __DIR__.'/../includes/header.php';?>
<div class="page-header"><div><h1>Receitas</h1><p class="muted">Total do período: <strong><?=money($total)?></strong></p></div></div><div class="table-card"><form class="form-row" method="get"><div class="form-group"><label>Início</label><input type="date" name="inicio" value="<?=e($inicio)?>"></div><div class="form-group"><label>Fim</label><input type="date" name="fim" value="<?=e($fim)?>"></div><button class="btn">Filtrar</button></form><table><thead><tr><th>Tipo</th><th>Quantidade</th><th>Total</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="3" class="empty">Sem receitas no período.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['tipo'])?></td><td><?=e($r['quantidade'])?></td><td><?=money($r['total'])?></td></tr><?php endforeach;endif;?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';?>
